/* Local help chatbot. Only the explicit feedback form sends to FormSubmit. */
(()=>{'use strict';
const mail='apuda.co.kr@gmail.com',endpoint='https://formsubmit.co/ajax/'+mail;
const menus={quiz:['✨ 나 알아보기','know-me.html'],explore:['🧭 기존 관심 탐색기','/#career-lab'],future:['🔮 미래의 변화','/#shiro-future'],life:['🏠 달라지는 생활','/#shiro-life'],career:['🎓 직업과 대학','/#shiro-career'],plan:['📚 나의 준비계획','/#shiro-plan'],news:['📰 AI·학습·서초고 소식','/#shiro-news'],home:['🏡 탐험 홈','/']};
const faqs=[
{keys:['시작','사용법','사용방법','어떻게','도움','처음'],text:'🐶 처음이면 이 순서로 해봐!\n① 나 알아보기: 24가지 질문으로 좋아하는 활동 찾기\n② 기존 관심 탐색기: 과목·활동을 고르고 직업 비교하기\n③ 준비계획: 작은 체험을 해보고 체크하기\n정답은 없어. 오늘 마음에 드는 것부터 시작하자!',links:['quiz','explore','plan']},
{keys:['흰둥이','챗봇','ai챗','인공지능'],text:'🐾 나는 이 홈페이지 사용법과 메뉴를 안내하는 흰둥이야. 미리 준비한 안내로 답하고, 대화는 외부 AI로 보내지 않아. 자유로운 진로 상담이 필요하면 질문 보내기로 운영자에게 남겨줘!',links:['quiz','explore']},
{keys:['질문검사','mbti','성향','취향','나알아','24','검사','적성'],text:'✨ 나 알아보기는 24개 질문으로 지금 끌리는 활동을 살펴봐. 약 5–7분 예상이고, 경험이 없으면 모르겠어를 골라도 돼. 정식 적성검사는 아니야. 결과는 직접 체험하면서 다시 살펴보자!',links:['quiz']},
{keys:['진로','탐색','비교','직업','학과','대학','과목'],text:'🧭 기존 관심 탐색기에서 관심 → 과목·활동 → 일하는 방식 → 비교·체험 순서로 골라봐. 30개 직업의 공부·학과·30분 체험을 보고 직업 2개를 비교할 수 있어. 합격 가능성을 판정하는 기능은 아니야.',links:['explore','career']},
{keys:['미래','10년','20년','30년','변화'],text:'🔮 미래의 변화에서 AI·로봇·건강·환경 등 여러 흐름과 10·20·30년 뒤의 가능성을 살펴봐. 먼 미래의 설명은 확정된 예측이 아니라 조건에 따라 달라지는 시나리오야.',links:['future','life']},
{keys:['뉴스','소식','서초','학교','급식','학습'],text:'📰 오늘의 AI 소식에서 AI·학습·학교 관련 공식 안내를 확인해봐. 뉴스에는 갱신 시각과 원문 링크가 있어. 서초고 공지는 공식 학교 링크도 확인해줘. 자동 수집이 모든 학교 공지를 포함하지는 않아.',links:['news']},
{keys:['공부','계획','준비','체험','실천'],text:'📚 한 번에 크게 하지 않아도 괜찮아! 준비계획에서 주 2시간부터 작은 활동을 해봐. 직업의 30분 체험을 하고 재미·어려움·다시 해보고 싶은 마음을 기록하면 좋아.',links:['plan','explore']},
{keys:['저장','기록','동기화','기기','삭제','초기화'],text:'💾 선택·답변·체험은 지금 브라우저에 저장돼. 다른 기기로 자동 이동하지 않아. 기존 탐색기의 내 탐색 기록 지우기와 나 알아보기의 질문 기록 지우기는 각각의 기록을 지워. 브라우저 데이터를 지우면 기록이 사라질 수 있어.',links:['quiz','explore']},
{keys:['설치','앱','홈화면'],text:'📱 홈 화면에서 앱처럼 열 수 있어. 홈페이지의 앱으로 사용 버튼을 눌러 안내를 봐줘. 휴대폰 브라우저 메뉴의 홈 화면에 추가 또는 앱 설치를 사용하면 돼.',links:['home']},
{keys:['응원','힘들','실패','못하','모르겠','불안'],text:'💌 아직 모르는 건 앞으로 발견할 게 있다는 뜻이야. 오늘은 10분만 해봐도 좋아. 네 속도로 하나씩 경험해보자, 승준아!',links:['quiz','plan']}
];
function answer(text){const normalized=text.toLowerCase().replace(/\s/g,'');return faqs.slice(1).find(f=>f.keys.some(k=>normalized.includes(k)))||(faqs[0].keys.some(k=>normalized.includes(k))?faqs[0]:null)||{text:'🐶 그 질문은 내가 준비한 사용법 안내에서 찾지 못했어. 아래 메뉴를 골라보거나, 질문·개선사항 보내기로 운영자에게 남겨줘. 원하는 기능은 “직업 비교”, “뉴스”, “저장”처럼 말해줘!',links:['quiz','explore','news']}}
function route(){const match=location.hash.match(/^#shiro-(future|life|career|plan|news)$/);if(match){const b=document.querySelector('[data-page="'+match[1]+'"]');if(b)b.click()}}
window.addEventListener('hashchange',route);route();
const css=document.createElement('link');css.rel='stylesheet';css.href='shiro-help.css';document.head.append(css);
const launch=document.createElement('button');launch.className='shiro-launch';launch.type='button';launch.setAttribute('aria-label','흰둥이 도움말 열기');launch.setAttribute('aria-expanded','false');launch.setAttribute('aria-controls','shiro-panel');launch.innerHTML='<img src="shiro-letter.jpg" alt=""><span>🐶 흰둥이에게 물어봐</span>';document.body.append(launch);
const panel=document.createElement('section');panel.id='shiro-panel';panel.className='shiro-panel';panel.hidden=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-label','흰둥이 도움말');panel.innerHTML='<div class="shiro-head"><img src="shiro-letter.jpg" alt="편지를 물고 온 흰둥이"><div><strong>🐶 흰둥이 도우미</strong><small>사용법 · 메뉴 안내 · 의견 보내기</small></div><button type="button" aria-label="흰둥이 도움말 닫기">×</button></div><div class="shiro-scroll"><div class="shiro-quick"></div><div class="shiro-messages" role="log" aria-live="polite" aria-label="흰둥이 대화"></div><div class="shiro-feedback" hidden></div></div><form class="shiro-compose"><input aria-label="흰둥이에게 물어볼 사용법" maxlength="200" placeholder="직업 비교는 어떻게 해?"><button type="submit">묻기</button></form>';document.body.append(panel);
const quick=panel.querySelector('.shiro-quick'),messages=panel.querySelector('.shiro-messages'),feedback=panel.querySelector('.shiro-feedback'),scroll=panel.querySelector('.shiro-scroll'),compose=panel.querySelector('.shiro-compose');
function add(text,user=false,links=[]){const box=document.createElement('div');box.className='shiro-bubble'+(user?' shiro-user':'');const copy=document.createElement('div');copy.textContent=text;box.append(copy);if(links.length){const wrap=document.createElement('div');wrap.className='shiro-links';links.forEach(k=>{const a=document.createElement('a');a.className='shiro-link';a.href=menus[k][1];a.textContent=menus[k][0]+' →';wrap.append(a)});box.append(wrap)}messages.append(box);while(messages.children.length>12)messages.firstElementChild.remove();scroll.scrollTop=scroll.scrollHeight}
function ask(text){feedback.hidden=true;compose.hidden=false;add(text,true);if(/개선|문의|보내|건의|오류|버그|이메일/.test(text)){showFeedback();return}const result=answer(text);add(result.text,false,result.links)}
['처음 사용법','나 알아보기','직업 비교','미래의 변화','뉴스·학교 소식','공부 준비','저장·기록'].forEach(text=>{const b=document.createElement('button');b.type='button';b.className='shiro-chip';b.textContent=text;b.onclick=()=>ask(text);quick.append(b)});const fb=document.createElement('button');fb.type='button';fb.className='shiro-chip';fb.textContent='💌 질문·개선사항 보내기';fb.onclick=showFeedback;quick.append(fb);
add('안녕, 승준아! 🐾\n어디부터 볼지 고민이면 내가 도와줄게. 아래 버튼을 고르거나 사용법을 물어봐!',false,['quiz','explore']);
function open(){panel.hidden=false;launch.setAttribute('aria-expanded','true');compose.querySelector('input').focus()}
function close(){panel.hidden=true;launch.setAttribute('aria-expanded','false');launch.focus()}
launch.onclick=()=>panel.hidden?open():close();panel.querySelector('.shiro-head button').onclick=close;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden)close()});compose.onsubmit=e=>{e.preventDefault();const input=compose.querySelector('input'),text=input.value.trim();if(text){input.value='';ask(text)}};
function showFeedback(){feedback.hidden=false;compose.hidden=true;if(!feedback.children.length){feedback.innerHTML=`<h3>💌 질문·개선사항 보내기</h3><form id="shiro-feedback-form"><label for="shiro-kind">어떤 이야기야?</label><select id="shiro-kind" name="category"><option>사용 질문</option><option>개선 제안</option><option>오류 신고</option><option>기타 의견</option></select><label for="shiro-message">전하고 싶은 이야기</label><textarea id="shiro-message" name="message" minlength="5" maxlength="2000" required placeholder="어떤 화면에서 무엇이 궁금했는지 알려줘. (5~2,000자)"></textarea><label for="shiro-email">답장 받을 이메일 (선택)</label><input class="shiro-email" id="shiro-email" name="email" type="email" maxlength="254" placeholder="답장이 필요할 때만 입력"><div class="shiro-honey" aria-hidden="true"><label>Leave blank<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="shiro-consent"><input type="checkbox" required><span>입력한 내용과 선택 이메일을 FormSubmit 전송 서비스로 보내 ${mail}에 전달하는 데 동의해요. 서비스는 제출 내용을 30일 보관합니다. 학교명·실명·성적·연락처는 적지 않아도 돼요.</span></label><p class="shiro-small">흰둥이 대화와 검사 답변은 함께 보내지 않아요. 비밀번호·인증번호는 입력하지 마세요.</p><button class="shiro-send" type="submit">💌 의견 보내기</button><div class="shiro-status" role="status" hidden></div><p class="shiro-small">메일 앱으로 직접 보내기: <a href="mailto:${mail}">${mail}</a></p></form>`;feedback.querySelector('form').onsubmit=sendFeedback}scroll.scrollTop=scroll.scrollHeight;feedback.querySelector('textarea').focus()}
let sending=false;
async function sendFeedback(e){e.preventDefault();const form=e.currentTarget;if(sending||!form.reportValidity())return;const data=new FormData(form),message=String(data.get('message')||'').trim();if(message.length<5)return;const status=form.querySelector('.shiro-status'),button=form.querySelector('.shiro-send');if(data.get('website'))return;sending=true;button.disabled=true;status.hidden=false;status.textContent='편지를 전달하는 중이에요…';const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);try{const payload={_subject:'[미래 나침반] '+String(data.get('category')),category:String(data.get('category')),message,source:'Future Compass / Shiro Help',_template:'table',_url:location.origin+location.pathname};const email=String(data.get('email')||'').trim();if(email)payload.email=email;const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(payload),signal:controller.signal});const result=await response.json();if(!response.ok)throw Error('request');if(/activat|confirm.*email/i.test(result.message||'')){status.textContent='수신 주소 인증이 아직 필요해요. 운영자가 FormSubmit 인증 메일을 확인하면 홈페이지 전송을 사용할 수 있어요. 지금은 아래 이메일 링크로 직접 보내주세요.';return}if(result.success!==true&&result.success!=='true')throw Error('service');status.textContent='전송 서비스가 요청을 접수했어요. 💌\n메일 도착 여부는 운영자 수신함에서 확인해야 해요. 수신 주소의 최초 인증이 필요한 경우 전달이 지연될 수 있어요.';form.querySelector('textarea').value='';form.querySelector('.shiro-email').value='';form.querySelector('input[type=checkbox]').checked=false}catch{status.textContent='전송 결과를 확인하지 못했어요. 내용은 그대로 남겨뒀어요. 아래 이메일 링크로 직접 보내거나 잠시 후 다시 시도해주세요.'}finally{clearTimeout(timeout);sending=false;button.disabled=false}}
})();
